def flatten(nested):
    out = []
    for x in nested:
        if isinstance(x, list):
            out.extend(flatten(x))
        else:
            out.append(x)
    return out

def depth(nested):
    return 1 + max((depth(x) for x in nested if isinstance(x, list)), default=0)

