def matmul(A, B):
    if len(A[0]) != len(B):
        raise ValueError(f"inner sizes differ: {len(A[0])} vs {len(B)}")
    n, m, p = len(A), len(B), len(B[0])
    C = [[0] * p for _ in range(n)]
    for i in range(n):
        for j in range(p):
            for k in range(m):
                C[i][j] += A[i][k] * B[k][j]
    return C

