def rbinary_search(items, target, lo=0, hi=None):
    if hi is None:
        hi = len(items) - 1
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if items[mid] == target:
        return mid
    if items[mid] < target:
        return rbinary_search(items, target, mid + 1, hi)
    return rbinary_search(items, target, lo, mid - 1)

xs = [1, 3, 5, 7, 9, 11]
