class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next

def ll_sum(node):
    if node is None:
        return 0
    return node.value + ll_sum(node.next)

def ll_max(node):
    if node is None:
        raise ValueError("empty list")
    if node.next is None:
        return node.value
    rest = ll_max(node.next)
    return node.value if node.value > rest else rest

def ll_to_list_reversed(node):
    if node is None:
        return []
    out = ll_to_list_reversed(node.next)
    out.append(node.value)
    return out

chain = Node(3, Node(8, Node(1)))
print(ll_sum(chain), ll_max(chain), ll_to_list_reversed(chain))
```

`ll_to_list_reversed` uses the call stack as the reversing device: values are appended on the way *back up*.

