import csv
import io
import statistics

def parse_rows(lines):
    rows = []
    for rec in csv.DictReader(lines):
        score = rec["score"].strip()
        rows.append({
            "student": rec["student_id"].strip(),
            "module": rec["module"].strip(),
            "lesson": rec["lesson"].strip(),
            "done": bool(rec["completed_at"].strip()),
            "score": int(score) if score else None,
        })
    return rows

def summarize(rows, key):
    groups = {}
    for r in rows:
        groups.setdefault(r[key], []).append(r)
    out = {}
    for name, rs in groups.items():
        scores = [r["score"] for r in rs if r["done"] and r["score"] is not None]
        done = sum(r["done"] for r in rs)
        out[name] = {
            "done": done,
            "total": len(rs),
            "pct": round(100 * done / len(rs), 1),
            "mean": round(statistics.fmean(scores), 1) if scores else None,
        }
    return out

def dedupe(rows):
    latest = {}
    for r in rows:
        latest[(r["student"], r["module"], r["lesson"])] = r
    return list(latest.values())

def not_started(rows):
    started = {r["student"] for r in rows if r["done"]}
    return sorted({r["student"] for r in rows} - started)

